<template><el-container><el-header><el-button @click="router.push('/health-shop')">返回健康商城</el-button><h3>优惠券详情</h3></el-header><el-main v-if="goods"><el-row :gutter="32"><el-col :xs="24" :md="12"><el-image src="/media/health-coupon.svg" fit="contain" style="width:100%"/></el-col><el-col :xs="24" :md="12"><h1>{{goods.title}}</h1><p class="price">¥{{goods.price}}</p><p>库存 {{goods.stock}} 份</p><p>活动开始 {{goods.start_time}}</p><p>活动结束 {{goods.end_time}}</p><el-statistic title="距离活动结束" :value="remaining" suffix="秒"/><el-alert title="仅供课程演示，本地结算不会真实扣款" type="info" :closable="false"/><el-button v-if="!order||['CANCELLED','EXPIRED'].includes(order.status)" type="primary" :disabled="!active" :loading="busy" @click="reserve">{{active?'立即秒杀':'活动未开始或已结束'}}</el-button><el-space v-else-if="order.status==='RESERVED'"><el-button v-if="payment.demoEnabled" type="primary" @click="pay">本地演示结算</el-button><el-button :disabled="!payment.sandboxConfigured" @click="sandbox">支付宝沙箱结算</el-button><el-button @click="cancel">退单</el-button><el-tag>待结算：{{order.expires_at}}</el-tag></el-space><el-tag v-else>已结算（付款渠道见订单核验）</el-tag></el-col></el-row></el-main><el-empty v-else description="商品不存在"/></el-container></template>
<script setup>
import{ref,computed,onMounted,onBeforeUnmount}from'vue';import{useRouter,useRoute}from'vue-router';import{call}from'@/api/health';import{ElMessage,ElMessageBox}from'element-plus';const router=useRouter(),route=useRoute(),goods=ref(),order=ref(),now=ref(Date.now()),busy=ref(false),payment=ref({});let timer;const remaining=computed(()=>goods.value?Math.max(0,Math.floor((new Date(goods.value.end_time).getTime()-now.value)/1000)):0),active=computed(()=>goods.value&&new Date(goods.value.start_time).getTime()<=now.value&&remaining.value>0);async function load(){payment.value=(await call('shop/payment-configuration')).data;goods.value=(await call('shop/goods')).data.find(g=>g.id===Number(route.params.id));order.value=(await call('shop/orders')).data.find(o=>o.goods_id===Number(route.params.id))}async function reserve(){busy.value=true;try{await call('shop/reserve/'+goods.value.id,'post');ElMessage.success('抢购成功');await load()}finally{busy.value=false}}async function cancel(){await ElMessageBox.confirm('同一商品退单三次后不可再抢购，确认退单？','退单');await call('shop/orders/'+order.value.id+'/cancel','post');await load()}async function pay(){await ElMessageBox.confirm('仅记录教学支付状态，不发生真实付款。','本地演示结算');await call('shop/orders/'+order.value.id+'/demo-pay','post');ElMessage.success('教学结算完成');await load()}async function sandbox(){const result=await call('shop/orders/'+order.value.id+'/checkout','post');window.location.assign(result.data.checkoutUrl)}onMounted(async()=>{await load();timer=setInterval(()=>now.value=Date.now(),1000)});onBeforeUnmount(()=>clearInterval(timer))
</script><style scoped>.el-header{display:flex;align-items:center;gap:24px}.el-main{padding:48px 6vw;background:#f1f7f6;min-height:90vh}.price{font-size:42px;color:#178a78}.el-alert{margin:24px 0}.el-button{margin-top:20px}</style>
